import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime#addWeeks
 */
public class MutableDateTime_addWeeks_TriageGen1Test {

    @Test
    public void testAddWeeks_PositiveValue() {
        // Initialize with a fixed date: 2023-01-01 (Sunday)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        int weeksToAdd = 2;

        dt.addWeeks(weeksToAdd);

        // 2023-01-01 + 2 weeks = 2023-01-15
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
        assertEquals(10, dt.getHourOfDay());
    }

    @Test
    public void testAddWeeks_ZeroValue() {
        // Initialize with a fixed date
        MutableDateTime dt = new MutableDateTime(2023, 5, 20, 12, 30, 0, 0);
        int weeksToAdd = 0;

        dt.addWeeks(weeksToAdd);

        // Since the code is: if (weeks > 0), adding 0 should result in no change
        assertEquals(2023, dt.getYear());
        assertEquals(5, dt.getMonthOfYear());
        assertEquals(20, dt.getDayOfMonth());
        assertEquals(12, dt.getHourOfDay());
        assertEquals(30, dt.getMinuteOfHour());
    }

    @Test
    public void testAddWeeks_NegativeValue() {
        // Initialize with a fixed date
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        int weeksToAdd = -1;

        dt.addWeeks(weeksToAdd);

        // Since the code is: if (weeks > 0), adding -1 should result in no change
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_CrossingMonthBoundary() {
        // January 25th + 1 week = February 1st
        MutableDateTime dt = new MutableDateTime(2023, 1, 25, 0, 0, 0, 0);
        dt.addWeeks(1);

        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_CrossingYearBoundary() {
        // December 25th + 2 weeks = January 8th next year
        MutableDateTime dt = new MutableDateTime(2023, 12, 25, 0, 0, 0, 0);
        dt.addWeeks(2);

        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(8, dt.getDayOfMonth());
    }
}
